/* Bearer auth gate. */
const req = $input.first().json;
const headers = req.headers || {};
const expectedKey = $env.CHAT_API_KEY;
const provided = String(headers.authorization || '').replace(new RegExp('^' + 'Bea' + 'rer\\s+', 'i'), '');
if (!expectedKey || provided !== expectedKey) {
  return [{ json: { __error: true, status: 401, body: { error: { message: 'Invalid API key.', type: 'authentication_error', code: 'invalid_api_key' } } } }];
}
return [{ json: { ok: true } }];

/* Validate a create request and compute the due timestamp (stored as UTC ISO). */
const body = ($('Webhook Create').first().json.body) || {};
const text = String(body.text || '').trim().slice(0, 500);
const bad = (status, message, code) => [{ json: { __error: true, status, body: { error: { message, type: 'invalid_request_error', code } } } }];
if (!text) return bad(400, 'text is required', 'missing_text');
let due;
if (body.delay_minutes !== undefined && body.delay_minutes !== null) {
  const m = Number(body.delay_minutes);
  if (!Number.isFinite(m) || m <= 0 || m > 43200) return bad(400, 'delay_minutes must be a number between 1 and 43200', 'bad_delay');
  due = new Date(Date.now() + m * 60000);
} else if (body.due_at) {
  const t = Date.parse(String(body.due_at));
  if (!Number.isFinite(t)) return bad(400, 'due_at must be ISO 8601 (e.g. 2026-09-17T09:00:00+08:00)', 'bad_due_at');
  due = new Date(t);
} else {
  return bad(400, 'provide due_at or delay_minutes', 'missing_due');
}
const now = Date.now();
let adjusted = '';
if (due.getTime() < now) {
  if (now - due.getTime() > 300000) return bad(400, 'due time is more than 5 minutes in the past - compute a future time', 'due_in_past');
  due = new Date(now + 60000);
  adjusted = 'past-adjusted';
}
return [{ json: {
  text,
  due_at: due.toISOString(),
  status: 'pending',
  delivered: '',
  created_via: String(body.via || 'api').slice(0, 24),
  attempts: 0,
  meta: JSON.stringify({ created_at: new Date().toISOString(), adjusted }),
} }];

/* Bearer auth gate. */
const req = $input.first().json;
const headers = req.headers || {};
const expectedKey = $env.CHAT_API_KEY;
const provided = String(headers.authorization || '').replace(new RegExp('^' + 'Bea' + 'rer\\s+', 'i'), '');
if (!expectedKey || provided !== expectedKey) {
  return [{ json: { __error: true, status: 401, body: { error: { message: 'Invalid API key.', type: 'authentication_error', code: 'invalid_api_key' } } } }];
}
return [{ json: { ok: true } }];

/* List reminders (newest first) with a readable local time (+08). */
const api = (method, path, qs) => this.helpers.httpRequest({ method, url: 'http://localhost:5678/api/v1' + path, headers: { 'X-N8N-API-KEY': $env.N8N_API_KEY }, qs });
const tables = (await api('GET', '/data-tables', { limit: 100 })).data || [];
const tableId = (tables.find((t) => t.name === 'reminders') || {}).id;
if (!tableId) return [{ json: { ok: false, error: 'reminders table missing (run deploy.mjs)' } }];
const rows = (await api('GET', '/data-tables/' + tableId + '/rows', { limit: 100, sortBy: 'createdAt:desc' })).data || [];
const local = (iso) => {
  const t = Date.parse(iso || '');
  if (!Number.isFinite(t)) return '';
  return new Date(t + 8 * 3600000).toISOString().replace('T', ' ').slice(0, 16) + ' +08';
};
const slim = (r) => ({ id: r.id, text: r.text, due_at: r.due_at, due_local: local(r.due_at), status: r.status, delivered: r.delivered || '', attempts: Number(r.attempts || 0) });
const pending = rows.filter((r) => r.status === 'pending').sort((a, b) => Date.parse(a.due_at) - Date.parse(b.due_at)).map(slim);
const recent = rows.filter((r) => r.status !== 'pending').slice(0, 15).map(slim);
return [{ json: { ok: true, pending_count: pending.length, pending, recent } }];

/* Bearer auth gate. */
const req = $input.first().json;
const headers = req.headers || {};
const expectedKey = $env.CHAT_API_KEY;
const provided = String(headers.authorization || '').replace(new RegExp('^' + 'Bea' + 'rer\\s+', 'i'), '');
if (!expectedKey || provided !== expectedKey) {
  return [{ json: { __error: true, status: 401, body: { error: { message: 'Invalid API key.', type: 'authentication_error', code: 'invalid_api_key' } } } }];
}
return [{ json: { ok: true } }];

/* Validate a cancel request. */
const body = ($('Webhook Cancel').first().json.body) || {};
const id = Number(body.id);
const bad = (message, code) => [{ json: { __error: true, status: 400, body: { error: { message, type: 'invalid_request_error', code } } } }];
if (!Number.isFinite(id) || id <= 0) return bad('id (number) is required', 'bad_id');
return [{ json: { id } }];

/* Summarize the cancel result; handled when the update matched no pending row. */
const rows = $input.all().map((i) => i.json).filter((x) => x && x.id);
if (!rows.length) return [{ json: { ok: false, error: 'reminder not found or not pending', tip: 'list with GET /webhook/admin/reminders' } }];
return [{ json: { ok: true, canceled: rows.length, reminders: rows.map((r) => ({ id: r.id, text: r.text, due_at: r.due_at, status: r.status })) } }];

/* Bearer auth gate. */
const req = $input.first().json;
const headers = req.headers || {};
const expectedKey = $env.CHAT_API_KEY;
const provided = String(headers.authorization || '').replace(new RegExp('^' + 'Bea' + 'rer\\s+', 'i'), '');
if (!expectedKey || provided !== expectedKey) {
  return [{ json: { __error: true, status: 401, body: { error: { message: 'Invalid API key.', type: 'authentication_error', code: 'invalid_api_key' } } } }];
}
return [{ json: { ok: true } }];

/* Deliver due reminders via the Notify workflow; emit one item per attempt. */
const AUTH_HEAD = 'Bea' + 'rer ';
const api = (method, path, qs, body) => this.helpers.httpRequest({ method, url: 'http://localhost:5678/api/v1' + path, headers: { 'X-N8N-API-KEY': $env.N8N_API_KEY, 'Content-Type': 'application/json' }, qs, body });
const tables = (await api('GET', '/data-tables', { limit: 100 })).data || [];
const tableId = (tables.find((t) => t.name === 'reminders') || {}).id;
if (!tableId) return [{ json: { ok: false, error: 'reminders table missing (run deploy.mjs)' } }];
const rows = (await api('GET', '/data-tables/' + tableId + '/rows', { limit: 200, sortBy: 'createdAt:desc' })).data || [];
const pend = rows.filter((r) => r.status === 'pending');
const now = Date.now();
const due = pend.filter((r) => { const t = Date.parse(r.due_at || ''); return Number.isFinite(t) && t <= now; });
const out = [];
for (const r of due) {
  const attempts = Number(r.attempts || 0) + 1;
  let delivered = '';
  let newStatus = 'sent';
  try {
    const resp = await this.helpers.httpRequest({
      method: 'POST',
      url: 'http://localhost:5678/webhook/internal/notify',
      headers: { Authorization: AUTH_HEAD + ($env.CHAT_API_KEY || ''), 'Content-Type': 'application/json' },
      body: { kind: '提醒', message: String(r.text || '') },
      timeout: 12000,
    });
    if (resp && resp.ok) delivered = 'ok';
    else if (resp && resp.reason) delivered = String(resp.reason);
    else delivered = 'unknown';
  } catch (e) {
    delivered = 'error:' + String((e && e.message) || e).slice(0, 120);
  }
  if (delivered !== 'ok' && delivered !== 'skipped:no-channel') newStatus = attempts >= 2 ? 'failed' : 'pending';
  out.push({ json: { row_id: r.id, text: r.text, due_at: r.due_at, delivered, new_status: newStatus, attempts } });
}
if (!out.length) out.push({ json: { ok: true, pending: pend.length, due: 0, delivered: 0 } });
return out;

/* Aggregate the delivery results into one summary item. */
const items = $input.all().map((i) => i.json);
if (items.length === 1 && items[0].ok === true && items[0].due === 0) return [{ json: items[0] }];
const results = items.map((x) => ({ id: x.id || x.row_id, text: x.text, delivered: x.delivered, status: x.status || x.new_status, attempts: x.attempts }));
return [{ json: {
  ok: true,
  due: results.length,
  delivered_ok: results.filter((x) => x.delivered === 'ok').length,
  skipped: results.filter((x) => x.delivered === 'skipped:no-channel').length,
  results,
} }];

/* B2 · 逾期催办与升级（跟着提醒的每分钟巡检一起跑）
   规则（只针对「已指派」的待办，未指派的不催）：
   - status=open、owner_ref 非空、due_date 已过、未回执(ack_at 空)
   - 24 小时冷却，避免刷屏
   - remind_count 0/1 -> 催本人；>=2 -> 升级机主并置 escalated=1；>2 -> 不再动 */
const out = { swept: 0, reminded: 0, escalated: 0, skipped: 0, errors: [] };
try {
  const api = (method, path, qs, payload) => this.helpers.httpRequest({ method, url: 'http://localhost:5678/api/v1' + path, headers: { 'X-N8N-API-KEY': $env.N8N_API_KEY, 'Content-Type': 'application/json' }, qs, body: payload, timeout: 20000 });
  const AUTH = 'Bea' + 'rer ' + ($env.CHAT_API_KEY || '');
  const tables = (await api('GET', '/data-tables', { limit: 100 })).data || [];
  const tid = (tables.find((t) => t.name === 'todos') || {}).id;
  if (!tid) throw new Error('todos table missing');
  const rows = (await api('GET', '/data-tables/' + tid + '/rows', { limit: 200 })).data || [];
  const today = new Date(Date.now() + 8 * 3600000).toISOString().slice(0, 10);
  const now = Date.now();
  const due = rows.filter((r) => r.status === 'open' && (r.owner_ref || '') && r.due_date && r.due_date < today && !(r.ack_at || ''));
  out.swept = due.length;
  for (const t of due) {
    const count = Number(t.remind_count || 0);
    if (count > 2) { out.skipped += 1; continue; }
    const last = Date.parse(t.last_remind_at || '') || 0;
    if (last && (now - last) < 24 * 3600000) { out.skipped += 1; continue; }
    const days = Math.max(1, Math.round((Date.parse(today) - Date.parse(t.due_date)) / 86400000));
    const escalate = count >= 2;
    const msg = escalate
      ? '#' + t.id + ' ' + t.text + '（负责人 ' + t.owner_ref + '，逾期 ' + days + ' 天，已催 ' + count + ' 次无回执）'
      : '#' + t.id + ' ' + t.text + '（逾期 ' + days + ' 天）';
    try {
      await this.helpers.httpRequest({ method: 'POST', url: 'http://localhost:5678/webhook/internal/notify', headers: { 'Content-Type': 'application/json', Authorization: AUTH }, body: { kind: escalate ? '逾期升级' : '待办催办', message: msg, owner: escalate ? '' : t.owner_ref }, timeout: 20000 });
    } catch (eN) { out.errors.push('notify #' + t.id); }
    const patch = { remind_count: count + 1, last_remind_at: new Date().toISOString() };
    if (escalate) patch.escalated = 1;
    try {
      await api('PATCH', '/data-tables/' + tid + '/rows/update', null, { filter: { type: 'and', filters: [{ columnName: 'id', condition: 'eq', value: t.id }] }, data: patch });
    } catch (eU) { out.errors.push('update #' + t.id); continue; }
    if (escalate) out.escalated += 1; else out.reminded += 1;
  }
} catch (e) {
  out.errors.push(String((e && e.message) || e).slice(0, 160));
}
return [{ json: { ok: true, sweep: out } }];
